'use strict';
const $=id=>document.getElementById(id), canvas=$('scene'),ctx=canvas.getContext('2d');
let lang='ta',time=0,running=false,last=0,answer=null;
const params=()=>({speed:Number($('speed').value),angle:Number($('angle').value),height:Number($('height').value)});
function solve({speed,angle,height}){const a=angle*Math.PI/180,vx=speed*Math.cos(a),vy=speed*Math.sin(a),flight=(vy+Math.sqrt(vy*vy+2*9.81*height))/9.81;return{vx,vy,flight,range:vx*flight,peak:height+vy*vy/(2*9.81)}}
function reset(){time=0;running=false;render()}
function feedback(){if(!answer)return;const correct=answer==='same';$('feedback').className=correct?'correct':'';$('feedback').textContent=lang==='en'?(correct?'Correct. ':'Try again. ')+'For a horizontal launch, t = √(2h/g). Horizontal speed changes the range, not the fall time.':(correct?'சரி. ':'மீண்டும் முயலுங்கள். ')+'கிடையாக எறியும்போது t = √(2h/g). கிடை வேகம் தூரத்தை மாற்றும்; விழும் நேரத்தை மாற்றாது.';}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-ta]').forEach(el=>el.textContent=el.dataset[lang]);$('language').textContent=lang==='ta'?'English ↗':'தமிழ் ↗';canvas.setAttribute('aria-label',lang==='ta'?'எறிய இயக்கப் பாதை மற்றும் வேகக் கூறுகள்':'Projectile trajectory and velocity vectors');feedback();render();window.dispatchEvent(new Event("iyal-language"))}
function render(){const p=params(),s=solve(p);['speed','angle','height'].forEach(k=>$(k+'-out').textContent=p[k]+(k==='angle'?'°':k==='speed'?' m/s':' m'));$('flight').textContent=s.flight.toFixed(2)+' s';$('range').textContent=s.range.toFixed(1)+' m';$('peak').textContent=s.peak.toFixed(1)+' m';$('clock').textContent='t = '+time.toFixed(2)+' s';$('launch').textContent=running?(lang==='ta'?'Ⅱ இடைநிறுத்து':'Ⅱ Pause'):(lang==='ta'?'▶ இயக்குக':'▶ Launch');draw(p,s)}
function arrow(x,y,dx,dy,color){if(Math.hypot(dx,dy)<2)return;ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+dx,y+dy);ctx.stroke();const a=Math.atan2(dy,dx);ctx.beginPath();ctx.moveTo(x+dx,y+dy);ctx.lineTo(x+dx-8*Math.cos(a-.45),y+dy-8*Math.sin(a-.45));ctx.lineTo(x+dx-8*Math.cos(a+.45),y+dy-8*Math.sin(a+.45));ctx.fill()}
function draw(p,s){const w=canvas.clientWidth,h=canvas.clientHeight,dpr=window.devicePixelRatio||1;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const left=43,bottom=h-49,scale=Math.min((w-76)/110,(h-75)/70),X=x=>left+x*scale,Y=y=>bottom-y*scale;ctx.font='11px Segoe UI';ctx.textAlign='center';for(let x=0;x<=110;x+=10){ctx.strokeStyle='#25414b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(X(x),20);ctx.lineTo(X(x),bottom);ctx.stroke();if(x%20===0){ctx.fillStyle='#8daab4';ctx.fillText(x+'',X(x),bottom+18)}}ctx.textAlign='right';for(let y=0;y<=60;y+=10){ctx.strokeStyle='#25414b';ctx.beginPath();ctx.moveTo(left,Y(y));ctx.lineTo(w-20,Y(y));ctx.stroke();ctx.fillStyle='#8daab4';ctx.fillText(y+'',left-9,Y(y)+4)}ctx.fillStyle='#b3c8ce';ctx.fillText('x (m)',w-18,bottom+18);ctx.textAlign='left';ctx.fillText('y (m)',9,15);ctx.strokeStyle='#6c929a';ctx.beginPath();ctx.moveTo(left,bottom);ctx.lineTo(w-20,bottom);ctx.stroke();ctx.setLineDash([4,6]);ctx.strokeStyle='#438782';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<=150;i++){const t=s.flight*i/150,x=X(s.vx*t),y=Y(Math.max(0,p.height+s.vy*t-4.905*t*t));i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#5de0ca';ctx.lineWidth=2.5;ctx.beginPath();for(let i=0;i<=100;i++){const t=time*i/100,x=X(s.vx*t),y=Y(Math.max(0,p.height+s.vy*t-4.905*t*t));i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();const x=X(s.vx*time),y=Y(Math.max(0,p.height+s.vy*time-4.905*time*time));if($('vectors').checked){arrow(x,y,s.vx*1.9,0,'#6ce3d3');arrow(x,y,0,-(s.vy-9.81*time)*1.9,'#ffc569')}ctx.beginPath();ctx.arc(x,y,13,0,Math.PI*2);ctx.fillStyle='#5de0ca22';ctx.fill();ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fillStyle='#a4fff0';ctx.fill();ctx.fillStyle='#aec6cd';ctx.font='12px Segoe UI';ctx.fillText(lang==='ta'?'பாதை முன்னோட்டம்':'Trajectory preview',left+10,30);}
function tick(now){if(running){time=Math.min(solve(params()).flight,time+Math.min((now-last)/1000,.05));if(time>=solve(params()).flight)running=false;render()}last=now;requestAnimationFrame(tick)}
['speed','angle','height'].forEach(k=>$(k).addEventListener('input',reset));$('vectors').addEventListener('change',render);$('reset').addEventListener('click',reset);$('launch').addEventListener('click',()=>{if(time>=solve(params()).flight)time=0;running=!running;render()});$('horizontal').addEventListener('click',()=>{$('angle').value=0;$('height').value=10;reset()});$('language').addEventListener('click',()=>{lang=lang==='ta'?'en':'ta';translate()});document.querySelectorAll('[data-answer]').forEach(el=>el.addEventListener('click',()=>{answer=el.dataset.answer;document.querySelectorAll('[data-answer]').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el))});feedback()}));window.addEventListener('resize',render);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_projectile',description:'Set projectile speed, angle and height, resetting the visible simulation.',inputSchema:{type:'object',properties:{speed:{type:'number',minimum:5,maximum:30},angle:{type:'number',minimum:0,maximum:80},height:{type:'number',minimum:0,maximum:20}},required:['speed','angle','height'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){for(const [k,min,max]of[['speed',5,30],['angle',0,80],['height',0,20]]){if(!Number.isInteger(input?.[k])||input[k]<min||input[k]>max)throw new Error('Invalid '+k)}for(const k of['speed','angle','height'])$(k).value=input[k];reset();return solve(params())}})).catch(()=>{})}catch{}}
render();requestAnimationFrame(tick);
